-- Seeded vehicles receive two extra images so automatic carousels are visible
-- immediately. User-uploaded vehicles retain only the images their owners add.
INSERT INTO tb_car_gallery_picture
  (file_name, file_type, image, display_order, id_car)
SELECT CONCAT('demo-car-side-', c.id_car, '.svg'), 'image/svg+xml',
  '',
  1, c.id_car
FROM tb_car c
JOIN tb_car_picture p ON p.id_car = c.id_car
WHERE p.file_name LIKE 'demo-car-%';

INSERT INTO tb_car_gallery_picture
  (file_name, file_type, image, display_order, id_car)
SELECT CONCAT('demo-car-interior-', c.id_car, '.svg'), 'image/svg+xml',
  '',
  2, c.id_car
FROM tb_car c
JOIN tb_car_picture p ON p.id_car = c.id_car
WHERE p.file_name LIKE 'demo-car-%';

INSERT INTO tb_car_listing_gallery_picture
  (file_name, file_type, image, display_order, id_listing)
SELECT CONCAT('demo-listing-side-', l.id_listing, '.svg'), 'image/svg+xml',
  '',
  1, l.id_listing
FROM tb_car_listing l
JOIN tb_car_listing_picture p ON p.id_listing = l.id_listing
WHERE p.file_name LIKE 'demo-listing-%';

INSERT INTO tb_car_listing_gallery_picture
  (file_name, file_type, image, display_order, id_listing)
SELECT CONCAT('demo-listing-interior-', l.id_listing, '.svg'), 'image/svg+xml',
  '',
  2, l.id_listing
FROM tb_car_listing l
JOIN tb_car_listing_picture p ON p.id_listing = l.id_listing
WHERE p.file_name LIKE 'demo-listing-%';
